210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner != null) {
212	            Pet currentPet = this.clinicService.findPetById(petId);
213	            if (currentPet != null) {
214	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
215	                currentPet.setName(petFieldsDto.getName());
216	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
217	                this.clinicService.savePet(currentPet);
218	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
227	        HttpHeaders headers = new HttpHeaders();
228	        Visit visit = visitMapper.toVisit(visitFieldsDto);
229	        Pet pet = new Pet();
230	        pet.setId(petId);
231	        visit.setPet(pet);
232	        this.clinicService.saveVisit(visit);
233	        VisitDto visitDto = visitMapper.toVisitDto(visit);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
235	            .buildAndExpand(visit.getId()).toUri());
236	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
237	    }
238	
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
243	        Owner owner = this.clinicService.findOwnerById(ownerId);
244	        if (owner != null) {
245	            Pet pet = owner.getPet(petId);
246	            if (pet != null) {
247	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    /**
254	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
255	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
256	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
257	     * blank (e.g. {@code "   "}). The offending field names are reported through an
258	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
259	     * as a 400 response carrying an {@code errors} array of field names.
260	     *
261	     * @param ownerFieldsDto the submitted owner fields
262	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
263	     */
264	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
265	        List<String> blankFields = new ArrayList<>();
266	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
267	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
268	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
269	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
270	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
271	        if (!blankFields.isEmpty()) {
272	            throw new InvalidOwnerFieldsException(blankFields);
273	        }
274	    }
275	
276	    private void addIfBlank(List<String> blankFields, String field, String value) {
277	        if (value != null && value.isBlank()) {
278	            blankFields.add(field);
279	        }
280	    }
281	
282	    /**
283	     * Normalizes an owner's optional email address. When present it is stored and returned
284	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
285	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
286	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
287	     * method runs.
288	     *
289	     * @param email the raw email value from the request, or {@code null} when omitted
290	     * @return the lower-cased email, or {@code null} when none was supplied
291	     */
292	    private String normalizeEmail(String email) {
293	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
294	    }
295	
296	    /**
297	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
298	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
299	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
300	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
301	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
302	     *
303	     * @param city the city of the owner being created
304	     * @param lastName the last name of the owner being created
305	     * @return the formatted customer code
306	     */
307	    private String nextCustomerCode(String city, String lastName) {
308	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
309	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
310	        long sequence = this.clinicService.findAllOwners().stream()
311	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
312	            .count() + 1L;
313	        return String.format("%s-%s-%04d", city3, last3, sequence);
314	    }
315	
316	    /**
317	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
318	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
319	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
320	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
321	     * new owner and surfaced as the read-only {@code namesakeCount} field.
322	     *
323	     * @param firstName the first name of the owner being created
324	     * @param lastName the last name of the owner being created
325	     * @return the number of existing owners with the same first and last name (case-insensitive)
326	     */
327	    private int namesakeCount(String firstName, String lastName) {
328	        return (int) this.clinicService.findAllOwners().stream()
329	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
330	                && equalsIgnoreCase(owner.getLastName(), lastName))
331	            .count();
332	    }
333	
334	    private boolean equalsIgnoreCase(String a, String b) {
335	        return a == null ? b == null : a.equalsIgnoreCase(b);
336	    }
337	
338	    /**
339	     * The maximum number of owners a single city may contain. Once a city already holds this many
340	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
341	     */
342	    private static final long MAX_OWNERS_PER_CITY = 50L;
343	
344	    /**
345	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
346	     * owners. Existing owners are matched to the requested city case-insensitively (using
347	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
348	     * the per-city counting used for the customer code. A city at capacity is reported through an
349	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
350	     * 409 Conflict response.
351	     *
352	     * @param city the city of the owner being created
353	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
354	     */
355	    private void rejectCityAtCapacity(String city) {
356	        long owners = this.clinicService.findAllOwners().stream()
357	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
358	            .count();
359	        if (owners >= MAX_OWNERS_PER_CITY) {
360	            throw new OwnerCityAtCapacityException(city);
361	        }
362	    }
363	
364	    /**
365	     * The maximum number of owners that may be registered on a single day. Once this many owners
366	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
367	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
368	     */
369	    private static final long MAX_OWNERS_PER_DAY = 100L;
370	
371	    /**
372	     * Resolves the effective registration date for a create request: the value supplied in the
373	     * request when present, otherwise the server's current date. The result is the raw effective
374	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
375	     *
376	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
377	     * @return the supplied date, or today when none was supplied
378	     */
379	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
380	        return suppliedDate != null ? suppliedDate : LocalDate.now();
381	    }
382	
383	    /**
384	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
385	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
386	     * the effective registration date so that a weekend value - whether supplied in the request or
387	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
388	     * registration date (such as the membership number's year segment and the daily create-limit
389	     * bucket) uses the adjusted business day.
390	     *
391	     * @param date the effective registration date
392	     * @return the same date when it is a weekday, otherwise the next Monday
393	     */
394	    private LocalDate businessDay(LocalDate date) {
395	        DayOfWeek dayOfWeek = date.getDayOfWeek();
396	        if (dayOfWeek == DayOfWeek.SATURDAY) {
397	            return date.plusDays(2);
398	        }
399	        if (dayOfWeek == DayOfWeek.SUNDAY) {
400	            return date.plusDays(1);
401	        }
402	        return date;
403	    }
404	
405	    /**
406	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
407	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
408	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
409	     * renders as a 429 Too Many Requests response.
410	     *
411	     * @param date the registration date of the owner being created (today)
412	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
413	     */
414	    private void rejectDailyRegistrationLimit(LocalDate date) {
415	        long owners = this.clinicService.findAllOwners().stream()
416	            .filter(owner -> date.equals(owner.getRegistrationDate()))
417	            .count();
418	        if (owners >= MAX_OWNERS_PER_DAY) {
419	            throw new DailyOwnerRegistrationLimitException(date);
420	        }
421	    }
422	
423	    /**
424	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
425	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
426	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
427	     */
428	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
429	
430	    /**
431	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
432	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
433	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
434	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
435	     * without a registration date, such as seed data) is never flagged.
436	     *
437	     * @param date the owner's registration date (the day it was created), or {@code null}
438	     * @return {@code true} if the day already holds more than the warning threshold of owners
439	     */
440	    private boolean bulkSignupWarning(LocalDate date) {
441	        if (date == null) {
442	            return false;
443	        }
444	        long owners = this.clinicService.findAllOwners().stream()
445	            .filter(owner -> date.equals(owner.getRegistrationDate()))
446	            .count();
447	        return owners > BULK_SIGNUP_WARNING_THRESHOLD;
448	    }
449	
450	    /**
451	     * Rejects a create request whose normalized telephone is already used by any existing owner.
452	     * Existing owners' telephones are reduced to the same canonical form (via
453	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
454	     * only in formatting still collide. A collision is reported through a
455	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
456	     * as a 409 Conflict response.
457	     *
458	     * @param normalizedTelephone the canonical telephone of the owner being created
459	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
460	     */
461	    private void rejectDuplicateTelephone(String normalizedTelephone) {
462	        boolean duplicate = existingOwnerMatches(
463	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
464	            normalizedTelephone);
465	        if (duplicate) {
466	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
467	        }
468	    }
469	
470	    /**
471	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
472	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
473	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
474	     * and the owner being created to the same canonical key and reject a match.
475	     *
476	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
477	     * @param key the canonical key of the owner being created
478	     * @return {@code true} if some existing owner shares the key
479	     */
480	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
481	        return this.clinicService.findAllOwners().stream()
482	            .map(keyExtractor)
483	            .filter(Objects::nonNull)
484	            .anyMatch(key::equals);
485	    }
486	
487	    /**
488	     * Rejects a create request that shares a household with an existing owner: another owner already
489	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
490	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
491	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
492	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
493	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
494	     * check when the request opts in via {@code sharesHousehold}.
495	     *
496	     * @param lastName the last name of the owner being created
497	     * @param address the address of the owner being created
498	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
499	     */
500	    private void rejectDuplicateHousehold(String lastName, String address) {
501	        String canonicalLastName = canonicalizeHousehold(lastName);
502	        String canonicalAddress = canonicalizeHousehold(address);
503	        if (canonicalLastName == null || canonicalAddress == null) {
504	            return;
505	        }
506	        boolean duplicate = this.clinicService.findAllOwners().stream()
507	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
508	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
509	        if (duplicate) {
510	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
511	        }
512	    }
513	
514	    /**
515	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
516	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
517	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
518	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
519	     *
520	     * @param value the raw field value, or {@code null}
521	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
522	     */
523	    private String canonicalizeHousehold(String value) {
524	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
525	    }
526	
527	    /**
528	     * Derives the stable, shared {@code householdId} for an owner joining a household via
529	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
530	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
531	     * owner with the same last name at the same address - regardless of casing or spacing - is
532	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
533	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
534	     *
535	     * @param lastName the last name of the owner being created
536	     * @param address the address of the owner being created
537	     * @return the shared household identifier
538	     */
539	    private String householdId(String lastName, String address) {
540	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
541	        try {
542	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
543	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
544	            StringBuilder sb = new StringBuilder(digest.length * 2);
545	            for (byte b : digest) {
546	                sb.append(String.format("%02X", b));
547	            }
548	            return sb.substring(0, 16);
549	        } catch (java.security.NoSuchAlgorithmException e) {
550	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
551	        }
552	    }
553	}
